// Eye CRM · Opportunity form: Pricing tab, Send to Production, Request Change, PL before Won.
// Rules run on the server in the "eye.pricing" Server Script.
(() => {
	const WON = ["Project Won", "Quote approved"];
	const OPEN = ["With Production", "In Pricing", "Returned to Sales", "Change Requested"];
	const api = (op, args = {}, opts = {}) =>
		frappe.call({ method: "eye.pricing", args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	const is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);

	frappe.ui.form.on("Opportunity", {
		refresh(frm) {
			const sales = is_sales();
			const st = frm.doc.custom_pricing_status;
			frm.__eye_prev_stage = frm.doc.sales_stage;

			frm.fields_dict.custom_costing.grid.update_docfield_property("margin", "read_only", sales ? 0 : 1);
			frm.set_df_property("custom_costing", "cannot_add_rows", 1);
			frm.set_df_property("custom_costing", "cannot_delete_rows", 1);
			frm.toggle_display(["custom_costing_sb", "custom_costing_table_sb"], (frm.doc.custom_costing || []).length > 0);

			render_summary(frm);
			if (frm.is_new()) return;

			const alerts = {
				Priced: [__("Pricing: Priced ✓"), "green"],
				"With Production": [__("Pricing: sent, Production has not started yet (you can still edit the requirements)"), "blue"],
				"In Pricing": [__("Pricing: Production is pricing"), "red"],
				"Returned to Sales": [__("Pricing: Production has a question, open the Pricing Request"), "orange"],
				"Change Requested": [__("Pricing: Production is changing the costs"), "orange"],
			};
			if (alerts[st]) frm.dashboard.set_headline_alert(...alerts[st]);

			const priced = new Set((frm.doc.custom_costing || []).map((c) => c.requirement));
			const to_price = (frm.doc.custom_requirements || []).filter((r) => !priced.has(r.name)).length;
			if (sales && !OPEN.includes(st) && to_price) {
				frm.add_custom_button(__("Send to Production"), () => send(frm)).addClass("btn-primary");
			}

			api("get_state", { opportunity: frm.doc.name }).then((s) => {
				frm.__eye_locked = new Set(s.locked || []);
				if (sales && frm.__eye_locked.size) {
					frm.add_custom_button(__("Request Change"), () => request_change(frm), __("Pricing"));
				}
				(s.pending || []).forEach((p) => {
					const link = `<a href="/app/pricing-change/${encodeURIComponent(p.name)}">${p.name}</a>`;
					const msg =
						p.requested_by_side === "Production"
							? __("Production asks to change the costs: review {0}", [link])
							: __("Your change request {0} is waiting for Production", [link]);
					frm.dashboard.add_comment(msg, p.requested_by_side === "Production" ? "orange" : "blue", true);
				});
			});
			render_requests(frm);
		},

		custom_default_margin(frm) {
			(frm.doc.custom_costing || []).forEach((r) => {
				frappe.model.set_value(r.doctype, r.name, "margin", frm.doc.custom_default_margin);
			});
		},

		items_remove: (frm) => render_summary(frm),

		sales_stage(frm) {
			const prev = frm.__eye_prev_stage;
			if (!WON.includes(frm.doc.sales_stage) || WON.includes(prev)) return;
			const revert = () => frm.set_value("sales_stage", prev);

			if (frm.doc.custom_pricing_status !== "Priced") {
				frappe.msgprint(__("Production must price all requirements before Project Won."));
				return revert();
			}
			const total = items_total(frm);
			if (total + 0.005 < flt(frm.doc.custom_total_selling)) {
				frappe.msgprint(
					__("Items total {0} is less than the minimum selling total {1}.", [
						format_currency(total, frm.doc.currency),
						format_currency(frm.doc.custom_total_selling, frm.doc.currency),
					])
				);
				return revert();
			}
			api("breakdown", { opportunity: frm.doc.name }).then((b) => show_pl(frm, b || {}, () => frm.save(), revert));
		},
	});

	frappe.ui.form.on("Opportunity Costing", {
		margin(frm, cdt, cdn) {
			const r = locals[cdt][cdn];
			frappe.model.set_value(cdt, cdn, "selling", flt(r.cost) * (1 + flt(r.margin) / 100));
			let cost = 0;
			let selling = 0;
			(frm.doc.custom_costing || []).forEach((c) => {
				cost += flt(c.cost);
				selling += flt(c.selling);
			});
			frm.set_value("custom_total_cost", cost);
			frm.set_value("custom_total_selling", selling);
			render_summary(frm);
		},
	});

	frappe.ui.form.on("Opportunity Item", {
		qty: (frm) => setTimeout(() => render_summary(frm), 300),
		rate: (frm) => setTimeout(() => render_summary(frm), 300),
		amount: (frm) => render_summary(frm),
	});

	function items_total(frm) {
		return (frm.doc.items || []).reduce((s, i) => s + (flt(i.amount) || flt(i.qty) * flt(i.rate)), 0);
	}

	function render_summary(frm) {
		const wrap = frm.fields_dict.custom_costing_summary && frm.fields_dict.custom_costing_summary.$wrapper;
		if (!wrap) return;
		if (!(frm.doc.custom_costing || []).length) {
			wrap.html("");
			return;
		}
		const fmt = (v) => format_currency(v, frm.doc.currency);
		const items = items_total(frm);
		const min = flt(frm.doc.custom_total_selling);
		const gap = items - min;
		const ok = gap >= -0.005;
		wrap.html(`
			<div class="row text-center" style="margin-top:8px">
				<div class="col-sm-4"><div class="text-muted">${__("Minimum selling total")}</div><h4>${fmt(min)}</h4></div>
				<div class="col-sm-4"><div class="text-muted">${__("Items total")}</div><h4>${fmt(items)}</h4></div>
				<div class="col-sm-4"><div class="text-muted">${ok ? __("Above minimum by") : __("Below minimum by")}</div>
					<h4 style="color:${ok ? "var(--green-600)" : "var(--red-600)"}">${fmt(Math.abs(gap))}</h4></div>
			</div>`);
	}

	function send(frm) {
		if (frm.is_dirty()) {
			frappe.msgprint(__("Save the Opportunity first."));
			return;
		}
		if (!frm.doc.custom_pricing_required_by) {
			frappe.msgprint(__("Set Required By in the Pricing tab first."));
			frm.scroll_to_field("custom_pricing_required_by");
			return;
		}
		api("send_to_production", { opportunity: frm.doc.name }, { freeze: true, freeze_message: __("Sending to Production...") }).then(
			(pr) => {
				const link = `<a href="/app/pricing-request/${encodeURIComponent(pr)}">${pr}</a>`;
				frappe.show_alert({ message: __("Sent to Production: {0}", [link]), indicator: "green" }, 8);
				frm.reload_doc();
			}
		);
	}

	function render_requests(frm) {
		const wrap = frm.fields_dict.custom_pricing_requests_html && frm.fields_dict.custom_pricing_requests_html.$wrapper;
		if (!wrap) return;
		frappe.db
			.get_list("Pricing Request", {
				filters: { opportunity: frm.doc.name },
				fields: ["name", "status", "required_by", "total_cost", "currency", "creation"],
				order_by: "creation desc",
				limit: 50,
			})
			.then((rows) => {
				if (!rows.length) {
					wrap.html(`<div class="text-muted">${__("No pricing requests yet.")}</div>`);
					return;
				}
				const colors = {
					"With Production": "blue",
					"In Pricing": "orange",
					"Returned to Sales": "yellow",
					"Change Requested": "yellow",
					Priced: "green",
				};
				const body = rows
					.map(
						(r) => `<tr>
					<td><a href="/app/pricing-request/${encodeURIComponent(r.name)}">${r.name}</a></td>
					<td><span class="indicator-pill ${colors[r.status] || "orange"}">${__(r.status || "With Production")}</span></td>
					<td>${frappe.datetime.str_to_user(r.required_by) || ""}</td>
					<td class="text-right">${r.status === "Priced" ? format_currency(r.total_cost, r.currency) : ""}</td>
					<td>${frappe.datetime.str_to_user(r.creation)}</td>
				</tr>`
					)
					.join("");
				wrap.html(`<table class="table table-bordered table-sm">
				<thead><tr><th>${__("Request")}</th><th>${__("Status")}</th><th>${__("Required By")}</th>
				<th class="text-right">${__("Total Cost")}</th><th>${__("Sent On")}</th></tr></thead>
				<tbody>${body}</tbody></table>`);
			});
	}

	function show_pl(frm, breakdown, on_confirm, on_cancel) {
		const fmt = (v) => format_currency(v, frm.doc.currency);
		const esc = frappe.utils.escape_html;
		const lines = (frm.doc.custom_costing || [])
			.map((c) => {
				const parts = (breakdown[c.requirement] || [])
					.map(
						(p) => `
				<tr class="text-muted small">
					<td style="padding-left:2em">↳ ${esc(p.item_code)}${p.supplier ? " · " + esc(p.supplier) : ""}</td>
					<td class="text-right">${flt(p.qty)}</td><td class="text-right">${fmt(p.amount)}</td><td></td><td></td>
				</tr>`
					)
					.join("");
				return `<tr><td><b>${esc(c.description || "")}</b></td><td class="text-right">${flt(c.qty)}</td>
				<td class="text-right">${fmt(c.cost)}</td><td class="text-right">${flt(c.margin)}%</td>
				<td class="text-right">${fmt(c.selling)}</td></tr>${parts}`;
			})
			.join("");
		const cost = flt(frm.doc.custom_total_cost);
		const min = flt(frm.doc.custom_total_selling);
		const items = items_total(frm);
		const gp = items - cost;
		const pct = cost ? (gp / cost) * 100 : 0;

		let done = false;
		const d = new frappe.ui.Dialog({
			title: __("PL before Project Won"),
			size: "extra-large",
			fields: [{ fieldtype: "HTML", fieldname: "pl" }],
			primary_action_label: __("Confirm → Won"),
			primary_action() {
				done = true;
				d.hide();
				on_confirm();
			},
		});
		d.fields_dict.pl.$wrapper.html(`
			<table class="table table-bordered">
				<thead><tr><th>${__("Requirement / Cost element")}</th><th class="text-right">${__("Qty")}</th>
				<th class="text-right">${__("Cost")}</th><th class="text-right">${__("Margin")}</th>
				<th class="text-right">${__("Selling")}</th></tr></thead>
				<tbody>${lines}</tbody>
			</table>
			<div class="row text-center">
				<div class="col-sm-3"><div class="text-muted">${__("Total cost")}</div><h4>${fmt(cost)}</h4></div>
				<div class="col-sm-3"><div class="text-muted">${__("Minimum selling")}</div><h4>${fmt(min)}</h4></div>
				<div class="col-sm-3"><div class="text-muted">${__("Items total")}</div><h4>${fmt(items)}</h4></div>
				<div class="col-sm-3"><div class="text-muted">${__("Gross profit")}</div><h4>${fmt(gp)} (${pct.toFixed(1)}%)</h4></div>
			</div>`);
		d.onhide = () => {
			if (!done) on_cancel();
		};
		d.show();
	}

	function request_change(frm) {
		const short = (t) => String(t || "").replace(/\s+/g, " ").trim().slice(0, 50);
		const rows = (frm.doc.custom_requirements || []).filter((r) => frm.__eye_locked.has(r.name));
		const opts = rows.map((r) => `${r.idx} · ${short(r.description)}`);
		const pick = (v) => rows[opts.indexOf(v)];
		const d = new frappe.ui.Dialog({
			title: __("Request Change"),
			fields: [
				{
					fieldtype: "Select",
					fieldname: "line",
					label: __("Requirement"),
					options: opts,
					reqd: 1,
					onchange() {
						const r = pick(d.get_value("line"));
						if (r) d.set_values({ description: r.description, qty: r.qty, notes: r.notes });
					},
				},
				{ fieldtype: "Small Text", fieldname: "description", label: __("New Description"), reqd: 1 },
				{ fieldtype: "Float", fieldname: "qty", label: __("New Qty") },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("New Notes") },
				{ fieldtype: "Small Text", fieldname: "reason", label: __("Reason"), reqd: 1 },
			],
			primary_action_label: __("Send to Production"),
			primary_action(v) {
				api(
					"request_requirement_change",
					{
						opportunity: frm.doc.name,
						requirement: pick(v.line).name,
						reason: v.reason,
						description: v.description,
						qty: v.qty,
						notes: v.notes,
					},
					{ freeze: true }
				).then(() => {
					d.hide();
					frm.reload_doc();
				});
			},
		});
		d.show();
		if (opts.length) d.set_value("line", opts[0]);
	}
})();

// Eye CRM · Opportunity Kanban: Sales works here, so pricing lives on the card.
// Card badges: pricing status and minimum selling vs items. Card menu: requirements, margin,
// quotation. Dragging to Quotation / Project Won is checked first and shows the PL.
// Uses nexlify.kanban.on (nexlify_core); rules run in the "eye.pricing" Server Script.
(() => {
	const kb = frappe.kanban_v2;
	if (!kb || !kb.extend_settings || !(window.nexlify && nexlify.kanban && nexlify.kanban.on)) return;
	if ((kb.settings.Opportunity || {}).__eye_crm) return; // already attached

	const WON = ["Project Won", "Quote approved"];
	const GUARDED = ["Quotation", ...WON];
	const THEME = { "With Production": "blue", "In Pricing": "amber", "Returned to Sales": "red", "Change Requested": "amber", Priced: "green" };
	const api = (op, args = {}, opts = {}) =>
		frappe.call({ method: "eye.pricing", args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	const money = (v, cur) => format_currency(flt(v), cur);
	const is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);

	nexlify.kanban.on("Opportunity", {
		card_badges({ card }) {
			const st = card.custom_pricing_status;
			const badges = [{ label: __(st || "Not priced"), theme: THEME[st] || "gray" }];
			const minimum = flt(card.custom_total_selling);
			if (minimum) {
				const items = flt(card.total || card.opportunity_amount);
				badges.push({
					label: `${__("Min")} ${money(minimum, card.currency)}`,
					theme: items + 0.005 >= minimum ? "green" : "red",
					variant: "ghost",
					tooltip: __("Items total: {0}", [money(items, card.currency)]),
				});
			}
			return badges;
		},

		card_menu({ card, name, refresh }) {
			return [
				{ label: __("Pricing Requirements"), icon: "list-checks", condition: is_sales, action: () => requirements_dialog(name, refresh) },
				{
					label: __("Set Margin"),
					icon: "percent",
					condition: () => is_sales() && card.custom_pricing_status === "Priced",
					action: () => margin_dialog(name, refresh),
				},
				{ label: __("Create Quotation"), icon: "file-text", condition: is_sales, action: () => make_quotation(name) },
				{ label: __("Open Pricing"), icon: "calculator", action: () => open_pricing(name) },
			];
		},

		async before_move({ name, names, to }) {
			if (!GUARDED.includes(to)) return;
			if (names.length > 1) {
				if (name === names[0]) frappe.msgprint(__("Move deals to {0} one at a time.", [__(to)]));
				return false;
			}
			const r = await api("kanban_check", { name, to });
			if (r.problems.length) {
				problems_dialog(name, to, r.problems);
				return false;
			}
			if (WON.includes(to) && r.costing) return pl_dialog(r);
		},
	});

	// ERPNext's own guard reads card.status, which on a Sales Stage board blocks the
	// "Quotation" column by mistake; on this board the server checks the move instead.
	kb.extend_settings("Opportunity", (base) => {
		const prev = base.callbacks && base.callbacks.canMoveCard;
		return {
			...base,
			__eye_crm: true,
			callbacks: {
				...(base.callbacks || {}),
				canMoveCard(card, from, to) {
					if (card && card.sales_stage === from) return true;
					return prev ? prev(card, from, to) : true;
				},
			},
		};
	});

	function problems_dialog(name, to, problems) {
		const d = new frappe.ui.Dialog({ title: __("Can't move to {0} yet", [__(to)]) });
		const actions = {
			requirements: [__("Pricing Requirements"), () => requirements_dialog(name)],
			quotation: [__("Create Quotation"), () => make_quotation(name)],
			margin: [__("Set Margin"), () => margin_dialog(name)],
			form: [__("Open Deal"), () => frappe.set_route("Form", "Opportunity", name)],
		};
		const $body = $(`<div class="flex flex-col gap-2"></div>`);
		problems.forEach((p) => {
			const $row = $(`<div class="flex items-center justify-between gap-3">
				<span>• ${frappe.utils.escape_html(p.text)}</span></div>`);
			const a = actions[p.action];
			if (a) {
				$(`<button class="btn btn-xs btn-default">${a[0]}</button>`)
					.on("click", () => {
						d.hide();
						a[1]();
					})
					.appendTo($row);
			}
			$body.append($row);
		});
		$(d.body).append($body);
		d.show();
	}

	function pl_dialog(r) {
		const esc = frappe.utils.escape_html;
		const lines = r.costing
			.map((c) => {
				const parts = (r.breakdown[c.requirement] || [])
					.map(
						(p) => `
				<tr class="text-muted small"><td style="padding-left:2em">↳ ${esc(p.item_code)}${p.supplier ? " · " + esc(p.supplier) : ""}</td>
				<td class="text-right">${flt(p.qty)}</td><td class="text-right">${money(p.amount, r.currency)}</td><td></td><td></td></tr>`
					)
					.join("");
				return `<tr><td><b>${esc(c.description || "")}</b></td><td class="text-right">${flt(c.qty)}</td>
				<td class="text-right">${money(c.cost, r.currency)}</td><td class="text-right">${flt(c.margin)}%</td>
				<td class="text-right">${money(c.selling, r.currency)}</td></tr>${parts}`;
			})
			.join("");
		const gp = r.items_total - r.total_cost;
		const pct = r.total_cost ? (gp / r.total_cost) * 100 : 0;
		return new Promise((resolve) => {
			let done = false;
			const d = new frappe.ui.Dialog({
				title: __("PL before Project Won"),
				size: "extra-large",
				primary_action_label: __("Confirm → Won"),
				primary_action() {
					done = true;
					d.hide();
					resolve(true);
				},
				onhide: () => {
					if (!done) resolve(false);
				},
			});
			$(d.body).html(`
				<table class="table table-bordered">
					<thead><tr><th>${__("Requirement / Cost element")}</th><th class="text-right">${__("Qty")}</th>
					<th class="text-right">${__("Cost")}</th><th class="text-right">${__("Margin")}</th><th class="text-right">${__("Selling")}</th></tr></thead>
					<tbody>${lines}</tbody></table>
				<div class="row text-center">
					<div class="col-sm-3"><div class="text-muted">${__("Total cost")}</div><h4>${money(r.total_cost, r.currency)}</h4></div>
					<div class="col-sm-3"><div class="text-muted">${__("Minimum selling")}</div><h4>${money(r.minimum, r.currency)}</h4></div>
					<div class="col-sm-3"><div class="text-muted">${__("Items total")}</div><h4>${money(r.items_total, r.currency)}</h4></div>
					<div class="col-sm-3"><div class="text-muted">${__("Gross profit")}</div><h4>${money(gp, r.currency)} (${pct.toFixed(1)}%)</h4></div>
				</div>`);
			d.show();
		});
	}

	async function requirements_dialog(name, after) {
		const p = await api("get_pricing", { name });
		const locked = p.requirements.filter((r) => r.locked).length;
		const d = new frappe.ui.Dialog({
			title: __("Pricing Requirements"),
			size: "large",
			fields: [
				{ fieldtype: "HTML", fieldname: "info" },
				{ fieldtype: "Date", fieldname: "required_by", label: __("Required By"), default: p.required_by },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Production"), default: p.notes },
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Requirements"),
					in_place_edit: true,
					data: p.requirements,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 5, reqd: 1 },
						{ fieldtype: "Float", fieldname: "qty", label: __("Qty"), in_list_view: 1, columns: 1, default: 1 },
						{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes"), in_list_view: 1, columns: 4 },
					],
				},
			],
			primary_action_label: p.open ? __("Save") : __("Save & Send to Production"),
			primary_action(v) {
				save(v, p.open ? 0 : 1);
			},
			secondary_action_label: p.open ? null : __("Save only"),
			secondary_action: p.open ? null : () => save(d.get_values(true), 0),
		});
		const msgs = [];
		if (p.status) msgs.push(__("Pricing status: {0}", [__(p.status)]));
		if (locked) msgs.push(__("{0} line(s) are already with Production; to change them use Request Change in the deal.", [locked]));
		d.fields_dict.info.$wrapper.html(msgs.map((m) => `<div class="text-muted small">${frappe.utils.escape_html(m)}</div>`).join(""));

		function save(v, send) {
			if (send && !v.required_by) {
				frappe.msgprint(__("Set Required By first."));
				return;
			}
			api("save_requirements", { name, rows: JSON.stringify(v.rows || []), required_by: v.required_by, notes: v.notes, send }).then(
				(pr) => {
					d.hide();
					frappe.show_alert({ message: pr ? __("Sent to Production: {0}", [pr]) : __("Saved"), indicator: "green" });
					after && after();
				}
			);
		}
		d.show();
	}

	async function margin_dialog(name, after) {
		const p = await api("get_pricing", { name });
		const d = new frappe.ui.Dialog({
			title: __("Set Margin"),
			size: "large",
			fields: [
				{
					fieldtype: "Percent",
					fieldname: "default_margin",
					label: __("Margin for all lines %"),
					default: p.default_margin,
					onchange() {
						const m = d.get_value("default_margin");
						if (m === null || m === undefined || m === "") return;
						d.fields_dict.rows.df.data.forEach((r) => (r.margin = m));
						d.fields_dict.rows.grid.refresh();
						summary();
					},
				},
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Costing"),
					in_place_edit: true,
					cannot_add_rows: true,
					cannot_delete_rows: true,
					data: p.costing,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 4, read_only: 1 },
						{ fieldtype: "Currency", fieldname: "cost", label: __("Cost"), in_list_view: 1, columns: 2, read_only: 1, options: "currency" },
						{ fieldtype: "Percent", fieldname: "margin", label: __("Margin %"), in_list_view: 1, columns: 2, onchange: () => summary() },
					],
				},
				{ fieldtype: "HTML", fieldname: "summary" },
			],
			primary_action_label: __("Save"),
			primary_action(v) {
				const margins = Object.fromEntries((v.rows || []).map((r) => [r.name, r.margin]));
				api("save_margins", { name, margins: JSON.stringify(margins), default_margin: v.default_margin }).then(() => {
					d.hide();
					frappe.show_alert({ message: __("Margin saved"), indicator: "green" });
					after && after();
				});
			},
		});
		function summary() {
			const rows = d.fields_dict.rows.df.data || [];
			const cost = rows.reduce((s, r) => s + flt(r.cost), 0);
			const min = rows.reduce((s, r) => s + flt(r.cost) * (1 + flt(r.margin) / 100), 0);
			const ok = p.items_total + 0.005 >= min;
			d.fields_dict.summary.$wrapper.html(`<div class="row text-center" style="margin-top:8px">
				<div class="col-sm-4"><div class="text-muted">${__("Total cost")}</div><h5>${money(cost, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Minimum selling")}</div><h5>${money(min, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Items total")}</div>
					<h5 style="color:${ok ? "var(--green-600)" : "var(--red-600)"}">${money(p.items_total, p.currency)}</h5></div></div>`);
		}
		d.show();
		summary();
	}

	function make_quotation(name) {
		frappe.model.open_mapped_doc({ method: "erpnext.crm.doctype.opportunity.opportunity.make_quotation", source_name: name });
